package com.terminallink.remote;import java.util.*;import android.view.*;import android.widget.*;
class MainActivity{String selectedId="tab-a";int FG=0,MUTED=1;Handler ui=new Handler();List<Map<String,Object>> sent=new ArrayList<>();int dp(int n){return n;}LinearLayout row(){return new LinearLayout(this);}TextView label(String t,int n,int c){TextView v=new TextView(this);v.setText(t);return v;}Button button(String t,View.Click l){Button b=new Button(this);b.setText(t);b.setOnClickListener(l);return b;}EditText input(String h,String t){EditText e=new EditText(this);e.setText(t);return e;}Object getSystemService(String s){return new android.view.inputmethod.InputMethodManager();}WindowManager getWindowManager(){return new WindowManager();}boolean inputReady(){return true;}static Map<String,Object> obj(Object... a){Map<String,Object> m=new HashMap<>();for(int i=0;i<a.length;i+=2)m.put((String)a[i],a[i+1]);return m;}void send(Map<String,Object> m){sent.add(m);}static class Handler{Map<Runnable,Long> queue=new LinkedHashMap<>();void postDelayed(Runnable r,long ms){queue.put(r,ms);}void removeCallbacks(Runnable r){queue.remove(r);}void tick(){List<Runnable> q=new ArrayList<>(queue.keySet());queue.clear();for(Runnable r:q)r.run();}}}
